css:
.ccm-matrix-heat{box-sizing:border-box;width:100%;max-width:400px;background:#0B0F17;border:1px solid #1C2432;border-radius:8px;padding:8px 9px 7px;font:9px/1.3 ui-monospace,Menlo,Consolas,monospace;color:#8B98B0;font-variant-numeric:tabular-nums}
.ccm-matrix-heat *{box-sizing:border-box}
.ccm-matrix-heat .hd{display:flex;justify-content:space-between;align-items:center;gap:6px;margin-bottom:6px}
.ccm-matrix-heat .tt{display:flex;flex-direction:column;min-width:0}
.ccm-matrix-heat .tt b{font:700 10px/1.2 system-ui,-apple-system,Segoe UI,sans-serif;color:#E4EBF7;letter-spacing:.06em}
.ccm-matrix-heat .tt span{font-size:7px;color:#5B6883;letter-spacing:.03em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ccm-matrix-heat .win{display:flex;gap:2px;flex:none}
.ccm-matrix-heat .win button{font:600 7.5px/1 ui-monospace,Menlo,Consolas,monospace;color:#7C8AA5;background:#111826;border:1px solid #22304A;border-radius:3px;padding:3px 4px;cursor:pointer}
.ccm-matrix-heat .win button:hover{color:#C9D4E6}
.ccm-matrix-heat .win button.on{color:#0B0F17;background:#C9D4E6;border-color:#C9D4E6}
.ccm-matrix-heat .win button:focus-visible,.ccm-matrix-heat .gd:focus-visible{outline:1.5px solid #6EA8FF;outline-offset:2px}
.ccm-matrix-heat .gd{display:grid;grid-template-columns:26px repeat(8,minmax(0,1fr));gap:1px;border-radius:3px}
.ccm-matrix-heat .gd span{height:18px;display:flex;align-items:center;justify-content:center;font-size:8px;white-space:nowrap;overflow:hidden}
.ccm-matrix-heat .gd .ch{height:12px;font-size:6.5px;color:#65728C;letter-spacing:.02em}
.ccm-matrix-heat .gd .rh{justify-content:flex-start;font-size:7px;color:#65728C}
.ccm-matrix-heat .gd .hl{color:#F4F7FC;font-weight:700}
.ccm-matrix-heat .gd .cl{cursor:crosshair;font-weight:600;border-radius:1px}
.ccm-matrix-heat .gd .dg{background:repeating-linear-gradient(45deg,#151B27 0 3px,#10151F 3px 6px);color:#48546C;font-weight:400}
.ccm-matrix-heat .gd .on{box-shadow:inset 0 0 0 1.5px #F4F7FC;position:relative;z-index:1}
.ccm-matrix-heat .gd .xs{box-shadow:inset 0 0 0 1px rgba(244,247,252,.35)}
.ccm-matrix-heat .lg{margin-top:7px}
.ccm-matrix-heat .cap{display:flex;justify-content:space-between;font-size:6.5px;color:#5B6883;letter-spacing:.06em;margin-bottom:2px}
.ccm-matrix-heat .bw{position:relative;height:8px}
.ccm-matrix-heat .bar{position:absolute;inset:0;border-radius:2px;border:1px solid #1C2432}
.ccm-matrix-heat .mk{position:absolute;top:-3px;width:3px;height:14px;margin-left:-1.5px;background:#F4F7FC;border:1px solid #0B0F17;border-radius:1px;transition:left .18s ease}
.ccm-matrix-heat .tk{position:relative;height:10px;margin-top:2px;font-size:6.5px;color:#65728C}
.ccm-matrix-heat .tk span{position:absolute;top:0;transform:translateX(-50%)}
.ccm-matrix-heat .tk span:nth-child(1){left:0;transform:none}
.ccm-matrix-heat .tk span:nth-child(2){left:25%}
.ccm-matrix-heat .tk span:nth-child(3){left:50%}
.ccm-matrix-heat .tk span:nth-child(4){left:75%}
.ccm-matrix-heat .tk span:nth-child(5){left:auto;right:0;transform:none}
.ccm-matrix-heat .rd{margin-top:5px;padding:5px 6px;background:#0F141F;border:1px solid #1A2232;border-radius:4px;min-height:36px}
.ccm-matrix-heat .rd .p{display:flex;align-items:baseline;gap:4px;white-space:nowrap;overflow:hidden}
.ccm-matrix-heat .rd .p b{color:#E4EBF7;font-size:10px}
.ccm-matrix-heat .rd .p i{font-style:normal;color:#4B5772}
.ccm-matrix-heat .rd .nm{color:#5B6883;font-size:7px;overflow:hidden;text-overflow:ellipsis;margin-left:2px}
.ccm-matrix-heat .rd .m{display:flex;flex-wrap:wrap;align-items:baseline;gap:2px 8px;margin-top:3px}
.ccm-matrix-heat .rd .m span{color:#5B6883;font-size:7px;letter-spacing:.05em;white-space:nowrap}
.ccm-matrix-heat .rd .m em{font-style:normal;color:#D6DFEF;font-size:9px;margin-left:3px}
.ccm-matrix-heat .rd .m em.po{color:#F2A063}
.ccm-matrix-heat .rd .m em.ne{color:#79AAF6}
.ccm-matrix-heat .rd .sg{padding:0 3px;border-radius:2px;border:1px solid #2A3650;color:#A9B6CC;font-size:7px}
.ccm-matrix-heat .rd .sg.ns{color:#5B6883;border-style:dashed}
.ccm-matrix-heat .ft{display:flex;flex-wrap:wrap;justify-content:space-between;gap:2px 6px;margin-top:5px;font-size:6.5px;color:#4B5772;letter-spacing:.03em}
.ccm-matrix-heat .ft span{white-space:nowrap}
.ccm-matrix-heat .ft .kh{color:#3E4960}
@media (prefers-reduced-motion:reduce){.ccm-matrix-heat .mk{transition:none}}

js:
var T=['ES1','NQ1','RTY1','TY1','RX1','DX1','GC1','CL1'];
var NM=['S&P 500 E-mini','Nasdaq-100 E-mini','Russell 2000 E-mini','UST 10Y Note','Euro-Bund','US Dollar Index','Gold 100oz','WTI Crude'];
var K=T.length,D=250,seed=20260923;
function rnd(){seed=seed+0x6D2B79F5|0;var t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;}
function g(){return Math.sqrt(-2*Math.log(rnd()||1e-9))*Math.cos(6.283185307*rnd());}
var R=[],d;
for(d=0;d<D;d++){
  var late=d>=175,eq=g(),rt=g(),us=g(),cm=g();
  var EQ=eq-(late?0.55:0.2)*rt;
  R.push([
    0.95*EQ+0.16*g(),
    1.10*EQ+0.42*g(),
    1.00*EQ+0.62*g()-0.12*rt,
    -0.70*rt+0.14*g()+(late?0:0.22)*eq,
    -0.52*rt+0.36*g(),
    0.62*us+0.16*rt-0.14*eq+0.22*g(),
    -0.48*us-0.26*rt+0.52*g(),
    0.80*cm+0.34*eq-0.14*us+0.46*g()
  ]);
}
var cache={};
function corr(n){
  if(cache[n])return cache[n];
  var X=R.slice(D-n),m=[],C=[],i,j,k;
  for(i=0;i<K;i++){var s0=0;for(k=0;k<n;k++)s0+=X[k][i];m[i]=s0/n;C[i]=[];}
  for(i=0;i<K;i++)for(j=i;j<K;j++){
    var sxy=0,sxx=0,syy=0;
    for(k=0;k<n;k++){var a=X[k][i]-m[i],b=X[k][j]-m[j];sxy+=a*b;sxx+=a*a;syy+=b*b;}
    C[i][j]=C[j][i]=(i===j)?1:sxy/Math.sqrt(sxx*syy);
  }
  return cache[n]=C;
}
var NEG=[58,126,232],MID=[23,29,41],POS=[236,132,56];
function cc(r){
  var t=Math.pow(Math.min(1,Math.abs(r)),0.85),c=r<0?NEG:POS,o=[0,1,2].map(function(q){return Math.round(MID[q]+(c[q]-MID[q])*t);});
  var L=(0.2126*o[0]+0.7152*o[1]+0.0722*o[2])/255;
  return ['rgb('+o.join(',')+')',L>0.42?'#0B0F17':'#E2E8F2'];
}
function f2(r){var a=Math.abs(r),t=a>=0.995?'1.00':a.toFixed(2).slice(1);return (r<0&&t!=='.00'?'−':'+')+t;}
var gd=root.querySelector('.gd'),rd=root.querySelector('.rd'),fa=root.querySelector('.fa'),mk=root.querySelector('.mk'),bts=root.querySelectorAll('.win button'),n=60,si=3,sj=0;
var st=[];for(d=0;d<=20;d++){var v=-1+d/10;st.push(cc(v)[0]+' '+(d*5)+'%');}
root.querySelector('.bar').style.background='linear-gradient(90deg,'+st.join(',')+')';
function draw(){
  var C=corr(n),h='<span class="c0"></span>',i,j,sum=0,cnt=0,hi=0;
  for(j=0;j<K;j++)h+='<span class="ch" data-j="'+j+'">'+T[j]+'</span>';
  for(i=0;i<K;i++){
    h+='<span class="rh" data-i="'+i+'">'+T[i]+'</span>';
    for(j=0;j<K;j++){
      var r=C[i][j];
      if(i===j){h+='<span class="cl dg" data-i="'+i+'" data-j="'+j+'" title="'+T[i]+' diagonal">1</span>';continue;}
      var x=cc(r);
      h+='<span class="cl" data-i="'+i+'" data-j="'+j+'" style="background:'+x[0]+';color:'+x[1]+'" title="'+T[i]+' / '+T[j]+' '+f2(r)+'">'+f2(r)+'</span>';
      if(j>i){sum+=r;cnt++;if(Math.abs(r)>=0.7)hi++;}
    }
  }
  gd.innerHTML=h;
  fa.textContent='ρ̄ '+f2(sum/cnt)+' · '+hi+'/'+cnt+' pairs |ρ|≥.70 · n='+n+' · 23-Sep-26';
  sel();
}
function sel(){
  var q=gd.querySelectorAll('.on,.hl,.xs'),k;
  for(k=0;k<q.length;k++)q[k].classList.remove('on','hl','xs');
  var c=gd.querySelector('.cl[data-i="'+si+'"][data-j="'+sj+'"]'),c2=gd.querySelector('.cl[data-i="'+sj+'"][data-j="'+si+'"]');
  if(c)c.classList.add('on');if(c2&&si!==sj)c2.classList.add('xs');
  var a=gd.querySelector('.rh[data-i="'+si+'"]'),b=gd.querySelector('.ch[data-j="'+sj+'"]');
  if(a)a.classList.add('hl');if(b)b.classList.add('hl');
  read();
}
function read(){
  var C=corr(n),r=C[si][sj];
  mk.style.left=((r+1)/2*100)+'%';
  if(si===sj){rd.innerHTML='<div class="p"><b>'+T[si]+'</b><span class="nm">'+NM[si]+'</span></div><div class="m"><span>diagonal · ρ ≡ 1.00 · select an off-diagonal cell</span></div>';return;}
  var tt=r*Math.sqrt((n-2)/(1-r*r)),z=0.5*Math.log((1+r)/(1-r)),se=1/Math.sqrt(n-3),lo=Math.tanh(z-1.96*se),up=Math.tanh(z+1.96*se);
  var L=corr(250)[si][sj],dl=Math.round(r*100)/100-Math.round(L*100)/100,cls=r<0?'ne':'po',sig=Math.abs(tt)>=1.96;
  rd.innerHTML='<div class="p"><b>'+T[si]+'</b><i>×</i><b>'+T[sj]+'</b><span class="nm">'+NM[si]+' / '+NM[sj]+'</span></div>'+
    '<div class="m"><span>ρ<em class="'+cls+'">'+f2(r)+(r<0?' ▼':' ▲')+'</em></span><span>t<em>'+(tt<0?'−':'+')+Math.abs(tt).toFixed(2)+'</em></span>'+
    '<span>CI95<em>['+f2(lo)+', '+f2(up)+']</em></span>'+
    (n===250?'':'<span>Δ vs 250D<em>'+f2(dl)+'</em></span>')+
    '<span class="sg'+(sig?'':' ns')+'">'+(sig?'SIG 5%':'n.s.')+'</span></div>';
}
function setN(v){n=v;for(var k=0;k<bts.length;k++){var on=+bts[k].getAttribute('data-n')===v;bts[k].classList.toggle('on',on);bts[k].setAttribute('aria-pressed',on?'true':'false');}draw();}
for(var b=0;b<bts.length;b++)bts[b].addEventListener('click',function(){setN(+this.getAttribute('data-n'));});
gd.addEventListener('mouseover',function(e){var c=e.target.closest('.cl');if(!c)return;si=+c.getAttribute('data-i');sj=+c.getAttribute('data-j');sel();});
gd.addEventListener('keydown',function(e){
  var k=e.key;
  if(k==='ArrowLeft')sj=Math.max(0,sj-1);
  else if(k==='ArrowRight')sj=Math.min(K-1,sj+1);
  else if(k==='ArrowUp')si=Math.max(0,si-1);
  else if(k==='ArrowDown')si=Math.min(K-1,si+1);
  else if(k==='t'||k==='T'){var x=si;si=sj;sj=x;}
  else if(k>='1'&&k<='4'){e.preventDefault();setN([20,60,120,250][+k-1]);return;}
  else return;
  e.preventDefault();sel();
});
draw();

css:
.ccm-rolling-corr{box-sizing:border-box;width:100%;max-width:400px;background:#0B0F17;border:1px solid #1C2432;border-radius:8px;padding:8px 9px 7px;font:9px/1.3 ui-monospace,Menlo,Consolas,monospace;color:#8B98B0;font-variant-numeric:tabular-nums}
.ccm-rolling-corr *{box-sizing:border-box}
.ccm-rolling-corr .hd{display:flex;justify-content:space-between;align-items:center;gap:6px;margin-bottom:5px}
.ccm-rolling-corr .tt{display:flex;flex-direction:column;min-width:0}
.ccm-rolling-corr .tt b{font:700 10px/1.2 system-ui,-apple-system,Segoe UI,sans-serif;color:#E4EBF7;letter-spacing:.06em}
.ccm-rolling-corr .tt .sub{font-size:7px;color:#5B6883;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ccm-rolling-corr .win,.ccm-rolling-corr .pr{display:flex;gap:2px}
.ccm-rolling-corr .pr{margin-bottom:6px}
.ccm-rolling-corr .pr button{flex:1}
.ccm-rolling-corr button{font:600 7.5px/1 ui-monospace,Menlo,Consolas,monospace;color:#7C8AA5;background:#111826;border:1px solid #22304A;border-radius:3px;padding:3px 5px;cursor:pointer;white-space:nowrap}
.ccm-rolling-corr button:hover{color:#C9D4E6}
.ccm-rolling-corr button.on{color:#0B0F17;background:#C9D4E6;border-color:#C9D4E6}
.ccm-rolling-corr button:focus-visible,.ccm-rolling-corr .cw:focus-visible{outline:1.5px solid #6EA8FF;outline-offset:2px}
.ccm-rolling-corr .cw{display:flex;gap:3px;border-radius:3px;cursor:crosshair}
.ccm-rolling-corr .pl{position:relative;flex:1;min-width:0;height:112px;background:#0D121C;border:1px solid #182030;border-radius:3px}
.ccm-rolling-corr svg{position:absolute;inset:0;width:100%;height:100%;display:block}
.ccm-rolling-corr .gl{stroke:#1B2333;stroke-width:1;stroke-dasharray:2 3;vector-effect:non-scaling-stroke}
.ccm-rolling-corr .zl{stroke:#3A4660;stroke-width:1;vector-effect:non-scaling-stroke}
.ccm-rolling-corr .av{stroke:#8B98B0;stroke-width:1;stroke-dasharray:4 3;vector-effect:non-scaling-stroke;opacity:.7}
.ccm-rolling-corr .ap{fill:rgba(236,132,56,.28)}
.ccm-rolling-corr .an{fill:rgba(58,126,232,.30)}
.ccm-rolling-corr .ln{fill:none;stroke:#E4EBF7;stroke-width:1.3;vector-effect:non-scaling-stroke;stroke-linejoin:round}
.ccm-rolling-corr .cx{stroke:#6EA8FF;stroke-width:1;vector-effect:non-scaling-stroke;opacity:0}
.ccm-rolling-corr .cw.act .cx{opacity:.8}
.ccm-rolling-corr .rg{position:absolute;left:4px;font-size:6.5px;letter-spacing:.06em;pointer-events:none}
.ccm-rolling-corr .rp{top:3px;color:#E8995E}
.ccm-rolling-corr .rn{bottom:3px;color:#7EA9F0}
.ccm-rolling-corr .dot{position:absolute;width:6px;height:6px;margin:-3px 0 0 -3px;border-radius:50%;background:#F4F7FC;border:1.5px solid #0B0F17;pointer-events:none;transition:left .12s linear,top .12s linear}
.ccm-rolling-corr .tip{position:absolute;top:3px;padding:2px 4px;background:#141B29;border:1px solid #2A3650;border-radius:3px;font-size:7.5px;color:#D6DFEF;white-space:nowrap;pointer-events:none;opacity:0}
.ccm-rolling-corr .cw.act .tip{opacity:1}
.ccm-rolling-corr .ya{position:relative;width:24px;flex:none;height:112px;font-size:6.5px;color:#5B6883}
.ccm-rolling-corr .ya span{position:absolute;left:0;transform:translateY(-50%);line-height:1}
.ccm-rolling-corr .ya span:first-child{transform:none}
.ccm-rolling-corr .ya span:nth-child(5){transform:translateY(-100%)}
.ccm-rolling-corr .lv{position:absolute;left:-2px;right:-3px;transform:translateY(-50%);padding:1px 1px;border-radius:2px;font-size:7px;font-weight:700;text-align:center;color:#0B0F17;line-height:1.2}
.ccm-rolling-corr .xa{position:relative;height:10px;margin:2px 27px 5px 0;font-size:6.5px;color:#5B6883}
.ccm-rolling-corr .xa span{position:absolute;top:0;transform:translateX(-50%);white-space:nowrap}
.ccm-rolling-corr .st{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:3px;border-top:1px solid #1C2432;padding-top:5px}
.ccm-rolling-corr .st div{display:flex;flex-direction:column;gap:1px;min-width:0}
.ccm-rolling-corr .st span{font-size:6px;letter-spacing:.08em;color:#4B5772;white-space:nowrap}
.ccm-rolling-corr .st b{font-size:9.5px;font-weight:600;color:#D6DFEF;white-space:nowrap}
.ccm-rolling-corr .st b.po{color:#F2A063}
.ccm-rolling-corr .st b.ne{color:#79AAF6}
.ccm-rolling-corr .ft{display:flex;flex-wrap:wrap;justify-content:space-between;gap:2px 6px;margin-top:5px;font-size:6.5px;color:#5B6883;letter-spacing:.03em}
.ccm-rolling-corr .ft span{white-space:nowrap}
.ccm-rolling-corr .ft .kh{color:#3E4960}
.ccm-rolling-corr .rgm b{color:#C9D4E6;font-weight:600}
@media (prefers-reduced-motion:reduce){.ccm-rolling-corr .dot{transition:none}}

js:
var M=504,WMAX=120,N=M+WMAX;
var PAIRS=[
  {a:'ES1',b:'TY1',na:'S&P 500 E-mini',nb:'UST 10Y Note',seed:7101,f:function(u){return u<0.52?-0.34+0.07*Math.sin(u*21):-0.34+0.80*Math.min(1,(u-0.52)/0.16)+0.06*Math.sin(u*27);}},
  {a:'ES1',b:'CL1',na:'S&P 500 E-mini',nb:'WTI Crude',seed:7202,f:function(u){return 0.22+0.12*Math.sin(u*9)+(u>0.30&&u<0.40?0.38*Math.sin((u-0.30)/0.10*Math.PI):0);}},
  {a:'GC1',b:'DX1',na:'Gold 100oz',nb:'US Dollar Index',seed:7303,f:function(u){return -0.48+0.40*Math.max(0,u-0.45)/0.55+0.07*Math.sin(u*17);}}
];
var DT=[],dt=new Date(Date.UTC(2026,8,23));
while(DT.length<N){var wd=dt.getUTCDay();if(wd!==0&&wd!==6)DT.unshift(new Date(dt.getTime()));dt.setUTCDate(dt.getUTCDate()-1);}
var MO=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function fd(x){return ('0'+x.getUTCDate()).slice(-2)+'-'+MO[x.getUTCMonth()]+'-'+String(x.getUTCFullYear()).slice(2);}
function gen(p){
  var s=p.seed;
  function rnd(){s=s+0x6D2B79F5|0;var t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;}
  function g(){return Math.sqrt(-2*Math.log(rnd()||1e-9))*Math.cos(6.283185307*rnd());}
  var X=[],Y=[];
  for(var t=0;t<N;t++){var r=Math.max(-0.95,Math.min(0.95,p.f(t/(N-1)))),a=g(),b=g();X.push(a*1.05);Y.push((r*a+Math.sqrt(1-r*r)*b)*0.62);}
  p.X=X;p.Y=Y;
}
function roll(p,W){
  var X=p.X,Y=p.Y,sx=0,sy=0,sxx=0,syy=0,sxy=0,out=[],t;
  for(t=0;t<N;t++){
    sx+=X[t];sy+=Y[t];sxx+=X[t]*X[t];syy+=Y[t]*Y[t];sxy+=X[t]*Y[t];
    if(t>=W){var o=t-W;sx-=X[o];sy-=Y[o];sxx-=X[o]*X[o];syy-=Y[o]*Y[o];sxy-=X[o]*Y[o];}
    if(t>=N-M){var c=sxy-sx*sy/W,vx=sxx-sx*sx/W,vy=syy-sy*sy/W;out.push(c/Math.sqrt(vx*vy));}
  }
  return out;
}
function f2(r){var a=Math.abs(r),t=a>=0.995?'1.00':a.toFixed(2).slice(1);return (r<0&&t!=='.00'?'−':'+')+t;}
var q=function(c){return root.querySelector(c);};
var cw=q('.cw'),pl=q('.pl'),dot=q('.dot'),tip=q('.tip'),lv=q('.lv'),cx=q('.cx'),xa=q('.xa');
var pi=0,W=60,S=[],cur=M-1,act=false;
PAIRS.forEach(gen);
function Y(v){return (1-v)/2*110;}
function draw(){
  var p=PAIRS[pi];S=roll(p,W);
  var ln='',ap='M0,55',an='M0,55',i,sum=0,mn=9,mx=-9,mi=0,xi=0;
  for(i=0;i<M;i++){
    var x=(i/(M-1)*300).toFixed(2),v=S[i];
    ln+=(i?'L':'M')+x+','+Y(v).toFixed(2);
    ap+='L'+x+','+Y(Math.max(v,0)).toFixed(2);an+='L'+x+','+Y(Math.min(v,0)).toFixed(2);
    sum+=v;if(v<mn){mn=v;mi=i;}if(v>mx){mx=v;xi=i;}
  }
  q('.ln').setAttribute('d',ln);q('.ap').setAttribute('d',ap+'L300,55Z');q('.an').setAttribute('d',an+'L300,55Z');
  var avg=sum/M,last=S[M-1],prev=S[M-22],le=0;
  for(i=0;i<M;i++)if(S[i]<=last)le++;
  var av=q('.av');av.setAttribute('y1',Y(avg));av.setAttribute('y2',Y(avg));
  q('.sub').textContent=p.a+' vs '+p.b+' · '+W+'D window · '+fd(DT[N-1]);
  function sv(c,v,sg){var e=q(c),z=Math.abs(v)<0.005;e.textContent=sg?f2(z?0:v):v;e.className=c.slice(1)+(sg&&!z?(v<0?' ne':' po'):'');}
  sv('.s0',last,1);sv('.s1',Math.round(last*100)/100-Math.round(prev*100)/100,1);sv('.s2',avg,1);sv('.s3',mn,1);sv('.s4',mx,1);sv('.s5',Math.round(le/M*100)+'th',0);
  q('.s3').title=fd(DT[N-M+mi]);q('.s4').title=fd(DT[N-M+xi]);
  lv.style.top=(Y(last)/110*100)+'%';lv.textContent=f2(last);lv.style.background=last<0?'#79AAF6':'#F2A063';
  var up=last>=0;
  q('.rgm').innerHTML='regime <b>'+(up?'▲ POSITIVE':'▼ NEGATIVE')+'</b> · '+(up?(p.b==='TY1'?'duration not hedging equity':'moving together'):'offsetting');
  var h='',lastQ=-1;
  for(i=0;i<M;i++){var d=DT[N-M+i],m=d.getUTCMonth(),k=d.getUTCFullYear()*12+m;
    if(m%3===0&&k!==lastQ&&(i===0||DT[N-M+i-1].getUTCMonth()!==m)){lastQ=k;var pc=i/(M-1)*100;if(pc>5&&pc<95)h+='<span style="left:'+pc.toFixed(2)+'%">'+MO[m]+(m===0?' '+String(d.getUTCFullYear()).slice(2):'')+'</span>';}}
  xa.innerHTML=h;
  put();
}
function put(){
  var i=act?cur:M-1,v=S[i],pc=i/(M-1)*100;
  dot.style.left=pc+'%';dot.style.top=(Y(v)/110*100)+'%';
  cx.setAttribute('x1',pc*3);cx.setAttribute('x2',pc*3);
  tip.textContent=fd(DT[N-M+i])+'  ρ'+W+' '+f2(v);
  if(pc>60){tip.style.left='auto';tip.style.right=(100-pc+2)+'%';}else{tip.style.right='auto';tip.style.left=(pc+2)+'%';}
  cw.classList.toggle('act',act);
}
function setBtn(sel,attr,val){var b=root.querySelectorAll(sel);for(var k=0;k<b.length;k++){var on=+b[k].getAttribute(attr)===val;b[k].classList.toggle('on',on);b[k].setAttribute('aria-pressed',on?'true':'false');}}
root.querySelector('.win').addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;W=+b.getAttribute('data-w');setBtn('.win button','data-w',W);draw();});
root.querySelector('.pr').addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;pi=+b.getAttribute('data-p');setBtn('.pr button','data-p',pi);draw();});
pl.addEventListener('mousemove',function(e){var r=pl.getBoundingClientRect();cur=Math.max(0,Math.min(M-1,Math.round((e.clientX-r.left)/r.width*(M-1))));act=true;put();});
pl.addEventListener('mouseleave',function(){act=false;put();});
cw.addEventListener('keydown',function(e){
  var k=e.key,st=e.shiftKey?21:1;
  if(k==='ArrowLeft')cur=Math.max(0,(act?cur:M-1)-st);
  else if(k==='ArrowRight')cur=Math.min(M-1,(act?cur:M-1)+st);
  else if(k==='Home')cur=0;else if(k==='End')cur=M-1;
  else if(k==='Escape'){act=false;put();return;}
  else return;
  e.preventDefault();act=true;put();
});
cw.addEventListener('blur',function(){act=false;put();});
draw();

