var TK=[
  {t:'NVDA',b:1.85,e:2.05,a:0.07,pos:5e6,ev:[96,5.8],seed:311},
  {t:'JPM',b:1.08,e:0.95,a:0.02,pos:5e6,ev:[62,-3.1],seed:312},
  {t:'XOM',b:0.52,e:1.25,a:-0.03,pos:5e6,ev:[40,3.6],seed:313},
  {t:'KO',b:0.42,e:0.72,a:0.01,pos:5e6,ev:[88,2.4],seed:314},
  {t:'TSLA',b:2.12,e:2.95,a:-0.05,pos:5e6,ev:[73,-9.2],seed:315}
];
var N=120,ESPX=6612.50,MULT=50,TC=1.980;
var DT=[],dt=new Date(Date.UTC(2026,8,23));
while(DT.length<N){var wd=dt.getUTCDay();if(wd!==0&&wd!==6)DT.unshift(new Date(dt.getTime()));dt.setUTCDate(dt.getUTCDate()-1);}
var MO=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function fd(x){return ('0'+x.getUTCDate()).slice(-2)+'-'+MO[x.getUTCMonth()];}
var sd=90210;
function rnd(){sd=sd+0x6D2B79F5|0;var t=Math.imul(sd^sd>>>15,1|sd);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;}
function g(){return Math.sqrt(-2*Math.log(rnd()||1e-9))*Math.cos(6.283185307*rnd());}
var X=[],i;
for(i=0;i<N;i++)X.push(g()*0.82*(rnd()<0.06?2.1:1));
TK.forEach(function(k){sd=k.seed;k.Y=X.map(function(x,j){return k.a+k.b*x+k.e*g()+(j===k.ev[0]?k.ev[1]:0);});});
function ols(Y){
  var mx=0,my=0,sxx=0,sxy=0,syy=0,j;
  for(j=0;j<N;j++){mx+=X[j];my+=Y[j];}mx/=N;my/=N;
  for(j=0;j<N;j++){var a=X[j]-mx,b=Y[j]-my;sxx+=a*a;sxy+=a*b;syy+=b*b;}
  var be=sxy/sxx,al=my-be*mx,sse=0;
  for(j=0;j<N;j++){var r=Y[j]-al-be*X[j];sse+=r*r;}
  var s=Math.sqrt(sse/(N-2));
  return {be:be,al:al,s:s,se:s/Math.sqrt(sxx),r2:1-sse/syy,rho:sxy/Math.sqrt(sxx*syy),mx:mx,sxx:sxx};
}
function sg(v,d){return (v<0?'−':'+')+Math.abs(v).toFixed(d);}
function mm(v){return (v<0?'−':'+')+'$'+Math.round(Math.abs(v)).toLocaleString('en-US');}
var q=function(c){return root.querySelector(c);};
var pw=q('.pw'),tip=q('.tip'),sel=q('.sel'),NS='http://www.w3.org/2000/svg';
var L=26,Rr=294,Tp=6,B=150,ci=0,cur=N-1,act=false,F,xr,yr;
function el(n,a){var e=document.createElementNS(NS,n);for(var k in a)e.setAttribute(k,a[k]);return e;}
function px(x){return L+(x+xr)/(2*xr)*(Rr-L);}
function py(y){return B-(y+yr)/(2*yr)*(B-Tp);}
function draw(){
  var k=TK[ci],Y=k.Y,j;F=ols(Y);
  var ax=0,ay=0;for(j=0;j<N;j++){ax=Math.max(ax,Math.abs(X[j]));ay=Math.max(ay,Math.abs(Y[j]));}
  var sx=ax>3?2:1,sy=ay>8?4:(ay>4?2:1),v;
  xr=Math.max(1,Math.ceil(ax/sx))*sx;yr=Math.max(1,Math.ceil(ay/sy))*sy;
  var gx=q('.gx');gx.textContent='';
  for(v=-xr;v<=xr;v+=sx){gx.appendChild(el('line',{x1:px(v),x2:px(v),y1:Tp,y2:B,'class':v===0?'z':''}));var t=el('text',{x:px(v),y:B+9,'text-anchor':'middle'});t.textContent=(v>0?'+':v<0?'−':'')+Math.abs(v);gx.appendChild(t);}
  for(v=-yr;v<=yr;v+=sy){gx.appendChild(el('line',{x1:L,x2:Rr,y1:py(v),y2:py(v),'class':v===0?'z':''}));var t2=el('text',{x:L-3,y:py(v)+2.5,'text-anchor':'end'});t2.textContent=(v>0?'+':v<0?'−':'')+Math.abs(v);gx.appendChild(t2);}
  var x0=-xr,x1=xr,y0=F.al+F.be*x0,y1=F.al+F.be*x1;
  function clip(xa,ya,xb,yb){if(Math.abs(ya)>yr){var xa2=((ya>0?yr:-yr)-F.al)/F.be;return[xa2,ya>0?yr:-yr];}return[xa,ya];}
  var p0=clip(x0,y0),p1=clip(x1,y1);
  var fit=q('.fit');fit.setAttribute('x1',px(p0[0]));fit.setAttribute('y1',py(p0[1]));fit.setAttribute('x2',px(p1[0]));fit.setAttribute('y2',py(p1[1]));
  var bx=Math.min(xr,yr),b1=q('.b1');b1.setAttribute('x1',px(-bx));b1.setAttribute('y1',py(-bx));b1.setAttribute('x2',px(bx));b1.setAttribute('y2',py(bx));
  var bt=q('.b1t');bt.setAttribute('x',px(bx)-18);bt.setAttribute('y',py(bx)-3);
  var up='',dn='',s;
  for(s=0;s<=40;s++){var xx=-xr+s/40*2*xr,w=TC*F.s*Math.sqrt(1/N+(xx-F.mx)*(xx-F.mx)/F.sxx),yh=Math.max(-yr,Math.min(yr,F.al+F.be*xx+w)),yl=Math.max(-yr,Math.min(yr,F.al+F.be*xx-w));up+=(s?'L':'M')+px(xx).toFixed(1)+','+py(yh).toFixed(1);dn='L'+px(xx).toFixed(1)+','+py(yl).toFixed(1)+dn;}
  q('.band').setAttribute('d',up+dn+'Z');
  var pts=q('.pts');pts.textContent='';
  for(j=0;j<N;j++){
    var r=Y[j]-F.al-F.be*X[j],ol=Math.abs(r)>2.5*F.s;
    pts.appendChild(el('circle',{cx:px(X[j]).toFixed(1),cy:py(Y[j]).toFixed(1),r:ol?3:1.9,'class':ol?'ol':''}));
    if(ol){var lt=el('text',{x:px(X[j])+(X[j]>0?-4:4),y:py(Y[j])+(Y[j]>0?-4:8),'text-anchor':X[j]>0?'end':'start'});lt.textContent=fd(DT[j])+' '+sg(r,1)+'%ε';pts.appendChild(lt);}
  }
  q('.axy').textContent=k.t+' %';
  q('.sub').textContent='daily ret vs SPX · '+N+'D · to '+fd(DT[N-1])+'-26';
  q('.eq').textContent='y = '+sg(F.al,3)+' '+(F.be<0?'−':'+')+' '+Math.abs(F.be).toFixed(2)+'x';
  function sv(c,h,cl){var e=q(c);e.innerHTML=h;e.className=c.slice(1)+(cl?' '+cl:'');}
  var aa=F.al*252;
  sv('.v0',F.be.toFixed(2)+' <small>±'+(TC*F.se).toFixed(2)+'</small>');
  sv('.v1',sg(aa,1)+'%',aa<0?'ne':'po');
  sv('.v2',F.r2.toFixed(2));
  sv('.v3',sg(F.rho,2));
  sv('.v4',(F.s*Math.sqrt(252)).toFixed(1)+'%');
  sv('.v5',String(N));
  var bd=Math.round(F.be*k.pos),cn=ESPX*MULT,nc=Math.round(bd/cn),res=bd-nc*cn;
  q('.hg').innerHTML='<div><span>POSITION</span><span><span class="by">LONG</span> <b>'+k.t+'</b> MV <b>$'+(k.pos/1e6).toFixed(2)+'M</b></span><span>β-$ <b>'+mm(bd)+'</b></span></div>'+
    '<div><span>HEDGE</span><span><span class="sl">SELL '+nc+'</span> ESZ6 @ '+ESPX.toFixed(2)+' ×'+MULT+'</span><span><b>'+mm(-nc*cn)+'</b></span></div>'+
    '<div><span>RESIDUAL</span><span class="mu">'+(Math.abs(res)/cn).toFixed(2)+' ct odd lot</span><span>β-$ <b>'+mm(res)+'</b></span></div>';
  put();
}
function put(){
  var Y=TK[ci].Y,j=cur,r=Y[j]-F.al-F.be*X[j],x=px(X[j]),y=py(Y[j]);
  if(!act){sel.setAttribute('visibility','hidden');pw.classList.remove('act');return;}
  sel.setAttribute('visibility','visible');
  sel.setAttribute('cx',x);sel.setAttribute('cy',y);
  tip.innerHTML='<b>'+fd(DT[j])+'-26</b> SPX '+sg(X[j],2)+'% · '+TK[ci].t+' '+sg(Y[j],2)+'%<br>fit '+sg(F.al+F.be*X[j],2)+'% · resid <span class="'+(r<0?'ne':'po')+'">'+sg(r,2)+'%</span> ('+sg(r/F.s,1)+'σ)';
  var pc=x/300*100;
  if(pc>55){tip.style.left='auto';tip.style.right='4px';}else{tip.style.right='auto';tip.style.left='4px';}
  tip.style.top=(y/172*100>50)?'4px':'auto';tip.style.bottom=(y/172*100>50)?'auto':'16px';
  pw.classList.add('act');
}
function setT(n){ci=n;var b=root.querySelectorAll('.tk button');for(var k=0;k<b.length;k++){var on=k===n;b[k].classList.toggle('on',on);b[k].setAttribute('aria-pressed',on?'true':'false');}draw();}
q('.tk').addEventListener('click',function(e){var b=e.target.closest('button');if(b)setT(+b.getAttribute('data-i'));});
pw.addEventListener('mousemove',function(e){
  var r=pw.getBoundingClientRect(),mx=(e.clientX-r.left)/r.width*300,my=(e.clientY-r.top)/r.height*172,best=1e9,bi=-1,Y=TK[ci].Y;
  for(var j=0;j<N;j++){var dx=px(X[j])-mx,dy=py(Y[j])-my,dd=dx*dx+dy*dy;if(dd<best){best=dd;bi=j;}}
  if(best<120){cur=bi;act=true;}else act=false;put();
});
pw.addEventListener('mouseleave',function(){act=false;put();});
pw.addEventListener('keydown',function(e){
  var k=e.key;
  if(k==='ArrowLeft'){cur=act?Math.max(0,cur-1):N-1;act=true;}
  else if(k==='ArrowRight'){cur=act?Math.min(N-1,cur+1):N-1;act=true;}
  else if(k>='1'&&k<='5'){setT(+k-1);}
  else if(k==='Escape'){act=false;}
  else return;
  e.preventDefault();put();
});
pw.addEventListener('blur',function(){act=false;put();});
draw();

