var TK=['XLK','XLC','XLY','XLF','XLI','XLB','XLE','XLU','XLRE','XLP','XLV'];
var NM=['Tech','Comm','Discr','Fins','Indus','Mats','Energy','Utils','REITs','Staples','Health'];
var LD=[[1.0,0.75,0,0,0,0.35],[0.9,0.6,0,0,0,0.5],[1.0,0.45,0.2,0,0,0.5],[0.95,0,0.6,0,0,0.45],[0.95,0,0.5,0,0,0.35],[0.9,0,0.45,0,0.25,0.45],[0.6,0,0.25,0,1.0,0.5],[0.45,0,0,0.8,0,0.5],[0.7,0,0.15,0.6,0,0.5],[0.55,0,0,0.55,0,0.45],[0.65,0,0,0.35,0,0.55]];
var n=TK.length,DN=250,sd=4417,i,j,t;
function rnd(){sd=sd+0x6D2B79F5|0;var q=Math.imul(sd^sd>>>15,1|sd);q=q+Math.imul(q^q>>>7,61|q)^q;return((q^q>>>14)>>>0)/4294967296;}
function g(){return Math.sqrt(-2*Math.log(rnd()||1e-9))*Math.cos(6.283185307*rnd());}
var R=[];for(i=0;i<n;i++)R.push([]);
for(t=0;t<DN;t++){var f=[g(),g(),g(),g(),g()];for(i=0;i<n;i++){var L=LD[i],v=L[5]*g();for(j=0;j<5;j++)v+=L[j]*f[j];R[i].push(v);}}
var C=[],Dm=[];
(function(){var m=[],s=[];for(i=0;i<n;i++){var a=0;for(t=0;t<DN;t++)a+=R[i][t];m[i]=a/DN;}
for(i=0;i<n;i++){C[i]=[];Dm[i]=[];}
for(i=0;i<n;i++)for(j=i;j<n;j++){var sxy=0,sxx=0,syy=0;for(t=0;t<DN;t++){var a=R[i][t]-m[i],b=R[j][t]-m[j];sxy+=a*b;sxx+=a*a;syy+=b*b;}
var r=i===j?1:sxy/Math.sqrt(sxx*syy);C[i][j]=C[j][i]=r;Dm[i][j]=Dm[j][i]=Math.sqrt(Math.max(0,0.5*(1-r)));}})();
var COL=['#6EA8FF','#F2A063','#25E07A','#C792EA','#F2C94C','#56CCF2','#FF8FA3','#9BE3C3','#B8C4D8','#E0B58A','#8FA7FF'];
function f2(r){var a=Math.abs(r),s=a>=0.995?'1.00':a.toFixed(2).slice(1);return (r<0&&s!=='.00'?'−':'+')+s;}
var q=function(c){return root.querySelector(c);};
var lb=q('.lb'),rc=q('.rc'),lnG=q('.ln'),gdG=q('.gd'),cut=q('.cut'),ctag=q('.ctag'),rng=q('.cr input'),kv=q('.kv'),cl=q('.cl'),ft=q('.ft'),bd=q('.bd');
var LK='avg',TREE,ORD,XM,cutv=0.30,seli=0,RH=13,NS='http://www.w3.org/2000/svg';
function build(){
  var act=[];for(i=0;i<n;i++)act.push({h:0,m:[i],leaf:i});
  while(act.length>1){
    var best=1e9,bi=0,bj=1,a,b;
    for(a=0;a<act.length;a++)for(b=a+1;b<act.length;b++){
      var A=act[a].m,B=act[b].m,s=0,mx=0,mn=1e9,x,y;
      for(x=0;x<A.length;x++)for(y=0;y<B.length;y++){var d=Dm[A[x]][B[y]];s+=d;if(d>mx)mx=d;if(d<mn)mn=d;}
      var v=LK==='avg'?s/(A.length*B.length):LK==='cpl'?mx:mn;
      if(v<best){best=v;bi=a;bj=b;}
    }
    var l=act[bi],r=act[bj];if(r.m.length<l.m.length){var tmp=l;l=r;r=tmp;}
    var nd={l:l,r:r,h:best,m:l.m.concat(r.m)};act.splice(bj,1);act.splice(bi,1,nd);
  }
  TREE=act[0];ORD=[];
  (function walk(nd){if(nd.leaf!==undefined){nd.y=ORD.length*RH+RH/2;ORD.push(nd.leaf);return;}walk(nd.l);walk(nd.r);nd.y=(nd.l.y+nd.r.y)/2;})(TREE);
  XM=Math.ceil((TREE.h+0.02)*20)/20;
  rng.max=XM.toFixed(2);
  var HS=[];(function hs(nd){if(nd.leaf!==undefined)return;HS.push(nd.h);hs(nd.l);hs(nd.r);})(TREE);HS.sort(function(a,b){return b-a;});
  cutv=Math.round((HS[2]+HS[3])/2*100)/100;
  var h='',k;
  for(k=0;k<=4;k++){var dv=XM*k/4,rv=1-2*dv*dv;h+='<span style="left:'+(k*25)+'%">'+(k?dv.toFixed(2).slice(1):'0')+'<br>'+(rv<0?'−':'')+Math.abs(rv).toFixed(2).replace(/^0/,'').replace('1.00','1')+'</span>';}
  q('.at').innerHTML=h;
  gdG.textContent='';
  for(k=1;k<4;k++){var ln=document.createElementNS(NS,'line');ln.setAttribute('x1',k*50);ln.setAttribute('x2',k*50);ln.setAttribute('y1',0);ln.setAttribute('y2',143);gdG.appendChild(ln);}
  render();
}
function X(h){return h/XM*200;}
function render(){
  rng.value=cutv;
  var cid=[],clus=[],k;
  (function asg(nd){if(nd.h<=cutv+1e-9){var c=clus.length;clus.push(nd);nd.m.forEach(function(x){cid[x]=c;});return;}asg(nd.l);asg(nd.r);})(TREE);
  var ordC=[],map={};ORD.forEach(function(x){if(map[cid[x]]===undefined){map[cid[x]]=ordC.length;ordC.push(clus[cid[x]]);}});
  ORD.forEach(function(x){cid[x]=map[cid[x]];});clus=ordC;
  var paths='';
  function seg(d,c){paths+='<path d="'+d+'" '+(c<0?'class="gy"':'style="stroke:'+COL[c%COL.length]+'"')+'></path>';}
  (function links(nd){
    if(nd.leaf!==undefined)return;
    [nd.l,nd.r].forEach(function(c){
      var cc=cid[c.m[0]],x0=X(c.h),x1=X(nd.h);
      if(nd.h<=cutv+1e-9)seg('M'+x0+','+c.y+'H'+x1+'V'+nd.y,cc);
      else{var xc=X(cutv);if(xc>x0)seg('M'+x0+','+c.y+'H'+xc,cc);seg('M'+Math.max(x0,xc)+','+c.y+'H'+x1+'V'+nd.y,-1);}
      links(c);
    });
  })(TREE);
  lnG.innerHTML=paths;
  var xc=X(cutv);cut.setAttribute('x1',xc);cut.setAttribute('x2',xc);
  ctag.style.left=(xc/2)+'%';ctag.textContent='k='+clus.length;
  if(xc>150){ctag.style.transform='translateX(-100%) translateX(-3px)';}else ctag.style.transform='translateX(3px)';
  kv.textContent='d≤'+cutv.toFixed(2).slice(1)+' · ρ≥'+f2(1-2*cutv*cutv)+' · k='+clus.length;
  var hl='',hr='';
  ORD.forEach(function(x,p){
    var c=cid[x],peers=clus[c].m.filter(function(y){return y!==x;}),s=0;
    peers.forEach(function(y){s+=C[x][y];});
    hl+='<div data-p="'+p+'"'+(p===seli?' class="on"':'')+'><b>'+TK[x]+'</b><i>'+NM[x]+'</i></div>';
    hr+='<div data-p="'+p+'"'+(p===seli?' class="on"':'')+'><em style="background:'+COL[c%COL.length]+'">C'+(c+1)+'</em><span>'+(peers.length?f2(s/peers.length):'solo')+'</span></div>';
  });
  lb.innerHTML=hl;rc.innerHTML=hr;
  var hc='';
  clus.forEach(function(nd,c){
    var m=nd.m,s=0,np=0,a,b;for(a=0;a<m.length;a++)for(b=a+1;b<m.length;b++){s+=C[m[a]][m[b]];np++;}
    var ms=ORD.filter(function(x){return m.indexOf(x)>=0;}).map(function(x){return TK[x];});
    hc+='<div><em style="background:'+COL[c%COL.length]+'">C'+(c+1)+'</em><span>'+ms.join(' ')+'</span><b>'+(np?'ρ̄'+f2(s/np):'—')+'</b><i>'+m.length+'</i></div>';
  });
  cl.innerHTML=hc;
  info();
}
function info(){
  var x=ORD[seli],hi=-2,lo=2,hj=0,lj=0;
  for(var y=0;y<n;y++){if(y===x)continue;if(C[x][y]>hi){hi=C[x][y];hj=y;}if(C[x][y]<lo){lo=C[x][y];lj=y;}}
  ft.innerHTML='<b>'+TK[x]+'</b> nearest '+TK[hj]+' '+f2(hi)+' · farthest '+TK[lj]+' '+f2(lo)+' · ↑↓ row ←→ cut';
  var rows=root.querySelectorAll('.lb div,.rc div');
  for(var k=0;k<rows.length;k++)rows[k].classList.toggle('on',+rows[k].getAttribute('data-p')===seli);
}
rng.addEventListener('input',function(){cutv=+rng.value;render();});
q('.lk').addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;LK=b.getAttribute('data-l');var bs=root.querySelectorAll('.lk button');for(var k=0;k<bs.length;k++){var on=bs[k]===b;bs[k].classList.toggle('on',on);bs[k].setAttribute('aria-pressed',on?'true':'false');}build();});
bd.addEventListener('mouseover',function(e){var r=e.target.closest('[data-p]');if(!r)return;seli=+r.getAttribute('data-p');info();});
bd.addEventListener('keydown',function(e){
  var k=e.key;
  if(k==='ArrowUp')seli=Math.max(0,seli-1);
  else if(k==='ArrowDown')seli=Math.min(n-1,seli+1);
  else if(k==='ArrowLeft'){cutv=Math.max(0.05,Math.round((cutv-0.01)*100)/100);render();}
  else if(k==='ArrowRight'){cutv=Math.min(XM,Math.round((cutv+0.01)*100)/100);render();}
  else return;
  e.preventDefault();info();
