var sd=5504;
function rnd(){sd=sd+0x6D2B79F5|0;var t=Math.imul(sd^sd>>>15,1|sd);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;}
function g(){return Math.sqrt(-2*Math.log(rnd()||1e-9))*Math.cos(6.283185307*rnd());}
var H=240,SH=120,ZW=60,GROSS=1000000,LP=[],LK=[],s=0,lpp=Math.log(168.2),c0=Math.log(70)-0.85*Math.log(168.2),t,i;
for(t=0;t<H;t++){lpp+=0.011*g();s=0.93*s+0.0055*g()+(t>=H-9?0.003:0);LP.push(lpp);LK.push(c0+0.85*lpp+s);}
var DT=[],dt=new Date(Date.UTC(2026,8,23));
while(DT.length<SH){var wd=dt.getUTCDay();if(wd!==0&&wd!==6)DT.unshift(new Date(dt.getTime()));dt.setUTCDate(dt.getUTCDate()-1);}
var MO=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function fd(x){return ('0'+x.getUTCDate()).slice(-2)+'-'+MO[x.getUTCMonth()];}
var B,A;
(function(){var n=120,mx=0,my=0,sxx=0,sxy=0;for(i=H-n;i<H;i++){mx+=LP[i];my+=LK[i];}mx/=n;my/=n;for(i=H-n;i<H;i++){sxx+=(LP[i]-mx)*(LP[i]-mx);sxy+=(LP[i]-mx)*(LK[i]-my);}B=sxy/sxx;A=my-B*mx;})();
var BASEK=LK[H-1],BASEP=LP[H-1],devS=0,devP=0;
var Z=[],S=[],MU=0,SG=1,HL=0,RHO=0,cur=SH-1,act=false,live=true,clock=14*3600+31*60+5;
function sg(v,d){return (v<0?'−':'+')+Math.abs(v).toFixed(d);}
function cm(v){return Math.round(v).toLocaleString('en-US');}
function calc(){
  S=[];for(i=0;i<H;i++)S.push(LK[i]-A-B*LP[i]);
  Z=[];
  for(t=H-SH;t<H;t++){var m=0,v=0,k;for(k=t-ZW+1;k<=t;k++)m+=S[k];m/=ZW;for(k=t-ZW+1;k<=t;k++)v+=(S[k]-m)*(S[k]-m);var sdv=Math.sqrt(v/(ZW-1));Z.push((S[t]-m)/sdv);if(t===H-1){MU=m;SG=sdv;}}
  var n=SH,xm=0,ym=0,sxx=0,sxy=0;for(t=H-n;t<H;t++){xm+=S[t-1];ym+=S[t]-S[t-1];}xm/=n;ym/=n;
  for(t=H-n;t<H;t++){var a=S[t-1]-xm,b=(S[t]-S[t-1])-ym;sxx+=a*a;sxy+=a*b;}
  var lam=sxy/sxx;HL=lam<0?-Math.LN2/Math.log(1+lam):Infinity;
  var rx=[],ry=[];for(t=H-ZW;t<H;t++){rx.push(LK[t]-LK[t-1]);ry.push(LP[t]-LP[t-1]);}
  var ax=0,ay=0,cxx=0,cyy=0,cxy=0;for(i=0;i<ZW;i++){ax+=rx[i];ay+=ry[i];}ax/=ZW;ay/=ZW;
  for(i=0;i<ZW;i++){cxx+=(rx[i]-ax)*(rx[i]-ax);cyy+=(ry[i]-ay)*(ry[i]-ay);cxy+=(rx[i]-ax)*(ry[i]-ay);}RHO=cxy/Math.sqrt(cxx*cyy);
}
var q=function(c){return root.querySelector(c);};
var cw=q('.cw'),pl=q('.pl'),dot=q('.dot'),tip=q('.tip'),cx=q('.cx'),lvb=q('.lv');
function Y(z){return 50-Math.max(-3.45,Math.min(3.45,z))/3.5*50;}
function draw(){
  calc();
  var d='',mk='',pos=0,cool=false,k;
  for(k=0;k<SH;k++){
    var x=k/(SH-1)*300,z=Z[k],pc=(x/3).toFixed(2);
    d+=(k?'L':'M')+x.toFixed(2)+','+Y(z).toFixed(2);
    if(cool&&Math.abs(z)<1)cool=false;
    if(pos===0&&!cool&&z>=2){pos=-1;mk+='<span class="en" style="left:'+pc+'%;top:'+(Y(z)-7)+'%" title="entry short spread '+fd(DT[k])+'">▼</span>';}
    else if(pos===0&&!cool&&z<=-2){pos=1;mk+='<span class="en" style="left:'+pc+'%;top:'+(Y(z)+7)+'%" title="entry long spread '+fd(DT[k])+'">▲</span>';}
    else if(pos!==0&&Math.abs(z)>=3){pos=0;cool=true;mk+='<span class="sp" style="left:'+pc+'%;top:'+Y(z)+'%" title="stop '+fd(DT[k])+'">✕</span>';}
    else if((pos===-1&&z<=0)||(pos===1&&z>=0)){pos=0;mk+='<span class="ex" style="left:'+pc+'%;top:50%" title="exit '+fd(DT[k])+'">●</span>';}
  }
  q('.ln').setAttribute('d',d);q('.mks').innerHTML=mk;
  var zn=Z[SH-1],zv=q('.zv');zv.textContent=sg(zn,2);zv.style.top=Y(zn)+'%';
  var pk=Math.round(Math.exp(LK[H-1])*100)/100,pp=Math.round(Math.exp(LP[H-1])*100)/100;
  var sig=q('.sig'),dir=pos!==0?pos:(zn>0?-1:1),state;
  if(Math.abs(zn)>=3){state='stp';q('.sa').textContent='✕ STOP · |z| ≥ 3';}
  else if(pos===-1){state='sh';q('.sa').textContent='▼ SHORT SPREAD';}
  else if(pos===1){state='lo';q('.sa').textContent='▲ LONG SPREAD';}
  else{state='';q('.sa').textContent=Math.abs(zn)<0.5?'● FLAT · exit zone':'○ WATCH · no entry';}
  sig.className='sig'+(state?' '+state:'');
  q('.sb').textContent=(dir<0?'sell KO / buy PEP':'buy KO / sell PEP')+' · tgt 0 · stop ±3';
  q('.v0').textContent=B.toFixed(3);
  q('.v1').textContent=sg(zn,2);
  q('.v2').textContent=sg((S[H-1]-MU)*1e4,0)+' bp';
  q('.v3').textContent=isFinite(HL)?HL.toFixed(1)+' d':'∞';
  q('.v4').textContent=(SG*1e4).toFixed(0)+' bp';
  q('.v5').textContent=sg(RHO,2);
  var nk=GROSS/(1+B),qk=Math.round(nk/pk),qp=Math.round(B*nk/pp),vk=Math.round(qk*pk)*(dir<0?-1:1),vp=Math.round(qp*pp)*(dir<0?1:-1);
  function row(tk,side,qty,px,v){return '<span><b>'+tk+'</b></span><span class="'+(side==='BUY'?'by':'sl')+'">'+side+'</span><span>'+cm(qty)+'</span><span>'+px.toFixed(2)+'</span><span>'+(v<0?'−':'+')+cm(Math.abs(v))+'</span>';}
  q('.l1').innerHTML=row('KO',dir<0?'SELL':'BUY',qk,pk,vk);
  q('.l2').innerHTML=row('PEP',dir<0?'BUY':'SELL',qp,pp,vp);
  q('.lt').innerHTML='<span class="ind">'+(pos!==0?'WORKING':'INDICATIVE')+' · β-neutral</span><span>GROSS <b>'+cm(Math.abs(vk)+Math.abs(vp))+'</b></span><span>NET <b>'+(vk+vp<0?'−':'+')+cm(Math.abs(vk+vp))+'</b></span>';
  var hh=Math.floor(clock/3600),mm=Math.floor(clock/60)%60,ss=clock%60;
  q('.clk').textContent='23-Sep-26 '+('0'+hh).slice(-2)+':'+('0'+mm).slice(-2)+':'+('0'+ss).slice(-2)+' ET · KO '+pk.toFixed(2)+' · PEP '+pp.toFixed(2);
  put();
}
function put(){
  var k=act?cur:SH-1,pc=k/(SH-1)*100;
  dot.style.left=pc+'%';dot.style.top=Y(Z[k])+'%';
  cx.setAttribute('x1',pc*3);cx.setAttribute('x2',pc*3);
  tip.textContent=fd(DT[k])+(k===SH-1?' (live)':'')+'  z '+sg(Z[k],2)+'  sprd '+sg((S[H-SH+k])*1e4,0)+'bp';
  if(pc>55){tip.style.left='auto';tip.style.right=(100-pc+2)+'%';}else{tip.style.right='auto';tip.style.left=(pc+2)+'%';}
  cw.classList.toggle('act',act);
}
function tick(){
  if (!root.isConnected) return;
  if(live){
    devP=0.97*devP+0.00045*g();devS=0.96*devS+0.00032*g();
    LP[H-1]=BASEP+devP;LK[H-1]=BASEK+B*devP+devS;
    clock+=1+Math.floor(rnd()*3);
    draw();
  }
  setTimeout(tick,900);
}
function setLive(v){live=v;lvb.classList.toggle('off',!v);lvb.setAttribute('aria-pressed',v?'true':'false');lvb.querySelector('span').textContent=v?'LIVE':'PAUSED';}
lvb.addEventListener('click',function(){setLive(!live);});
pl.addEventListener('mousemove',function(e){var r=pl.getBoundingClientRect();cur=Math.max(0,Math.min(SH-1,Math.round((e.clientX-r.left)/r.width*(SH-1))));act=true;put();});
pl.addEventListener('mouseleave',function(){act=false;put();});
cw.addEventListener('keydown',function(e){
  var k=e.key;
  if(k==='ArrowLeft'){cur=Math.max(0,(act?cur:SH-1)-(e.shiftKey?20:1));act=true;}
  else if(k==='ArrowRight'){cur=Math.min(SH-1,(act?cur:SH-1)+(e.shiftKey?20:1));act=true;}
  else if(k==='p'||k==='P'){setLive(!live);}
  else if(k==='Escape'){act=false;}
  else return;
  e.preventDefault();put();
});
cw.addEventListener('blur',function(){act=false;put();});
try{if(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches)setLive(false);}catch(err){}
draw();
setTimeout(tick,900);

