js:
var ROWS=[
  ['EQ','ES1','S&P 500 E-mini'],['EQ','VG1','Euro Stoxx 50'],['EQ','NK1','Nikkei 225'],
  ['RT','TY1','UST 10Y Note'],['RT','RX1','Euro-Bund'],['RT','JB1','JGB 10Y'],
  ['FX','EURUSD','EUR/USD spot'],['FX','USDJPY','USD/JPY spot'],['FX','AUDUSD','AUD/USD spot'],
  ['CM','GC1','Gold'],['CM','CL1','WTI Crude'],['CM','HG1','Copper'],
  ['RK','VX1','VIX future'],['RK','CDXHY','CDX HY 5Y sprd'],['RK','XBT','Bitcoin']
];
var ANC=['ES1','TY1','DX1'],WIN=[21,63,126,252],WL=['1M','3M','6M','1Y'],N=252,NR=ROWS.length;
var sd=60606;
function rnd(){sd=sd+0x6D2B79F5|0;var t=Math.imul(sd^sd>>>15,1|sd);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;}
function g(){return Math.sqrt(-2*Math.log(rnd()||1e-9))*Math.cos(6.283185307*rnd());}
var R=[],DX=[],t,i,j;for(i=0;i<NR;i++)R.push([]);
for(t=0;t<N;t++){
  var nw=t>=N-21,EQ=g(),RT=g(),US=g(),CM=g(),CR=g();
  var eq=EQ-(nw?0.9:0.1)*RT;
  var v=[
    eq+0.18*g(),
    0.85*eq+0.2*US+0.45*g(),
    0.7*eq+0.35*US+0.6*g(),
    -RT-(nw?0:0.38)*EQ+0.2*g(),
    -0.75*RT+0.1*EQ+0.45*g(),
    -0.35*RT+0.85*g(),
    -0.85*US+0.1*EQ+0.3*g(),
    0.6*US+0.35*RT+0.15*EQ+0.5*g(),
    -0.6*US+0.4*eq+0.2*CM+0.45*g(),
    -0.5*US-0.25*RT+(nw?0.75:0)*EQ+0.55*g(),
    CM+0.3*eq-0.1*US+0.5*g(),
    0.5*CM+0.45*eq-0.2*US+0.5*g(),
    -0.85*eq+0.35*g(),
    -0.7*eq+0.15*RT+0.5*g(),
    (nw?1.1:0.3)*eq+CR+0.4*g()
  ];
  for(i=0;i<NR;i++)R[i].push(v[i]);
  DX.push(US+0.2*RT-0.15*EQ+0.25*g());
}
function ser(a){return a===0?R[0]:a===1?R[3]:DX;}
function cor(x,y,w){var n=w,s=N-w,mx=0,my=0,k,sxy=0,sxx=0,syy=0;for(k=s;k<N;k++){mx+=x[k];my+=y[k];}mx/=n;my/=n;for(k=s;k<N;k++){var a=x[k]-mx,b=y[k]-my;sxy+=a*b;sxx+=a*a;syy+=b*b;}return sxy/Math.sqrt(sxx*syy);}
var NEG=[58,126,232],MID=[23,29,41],POS=[236,132,56];
function cc(r){var tt=Math.pow(Math.min(1,Math.abs(r)),0.85),c=r<0?NEG:POS,o=[0,1,2].map(function(k){return Math.round(MID[k]+(c[k]-MID[k])*tt);});var L=(0.2126*o[0]+0.7152*o[1]+0.0722*o[2])/255;return ['rgb('+o.join(',')+')',L>0.42?'#0B0F17':'#E2E8F2'];}
function f2(r){var a=Math.abs(r),s=a>=0.995?'1.00':a.toFixed(2).slice(1);return (r<0&&s!=='.00'?'−':'+')+s;}
function fz(r1,n1,r2,n2){var z1=0.5*Math.log((1+r1)/(1-r1)),z2=0.5*Math.log((1+r2)/(1-r2));return (z1-z2)/Math.sqrt(1/(n1-3)+1/(n2-3));}
var q=function(c){return root.querySelector(c);};
var gb=q('.gb'),dt=q('.dt'),AI=0,SC=-1,SD=-1,sel=0,TB=[];
var st=[];for(i=0;i<=10;i++)st.push(cc(-1+i/5)[0]+' '+(i*10)+'%');
q('.lg .bar').style.background='linear-gradient(90deg,'+st.join(',')+')';
function compute(){
  var an=ser(AI);TB=[];
  for(i=0;i<NR;i++){
    var isA=ROWS[i][1]===ANC[AI],c=[];
    for(j=0;j<4;j++)c.push(isA?1:cor(R[i],an,WIN[j]));
    TB.push({i:i,a:isA,c:c,d:isA?0:Math.round(c[0]*100)/100-Math.round(c[3]*100)/100,z:isA?0:fz(c[0],21,c[3],252)});
  }
}
function order(){
  var o=TB.slice();
  if(SC>=0)o.sort(function(a,b){if(a.a!==b.a)return a.a?1:-1;var va=SC===4?a.d:a.c[SC],vb=SC===4?b.d:b.c[SC];return (vb-va)*(SD<0?1:-1);});
  return o;
}
function draw(){
  var o=order(),h='',pg='';
  o.forEach(function(r,p){
    var R0=ROWS[r.i],gs=SC<0&&pg&&pg!==R0[0];pg=R0[0];
    h+='<div class="r'+(r.a?' ax':'')+(gs?' gs':'')+(p===sel?' on':'')+'" data-p="'+p+'" title="'+R0[2]+'"><span class="nm"><i>'+R0[0]+'</i>'+R0[1]+'</span>';
    for(j=0;j<4;j++){if(r.a){h+='<span title="anchor">1</span>';continue;}var x=cc(r.c[j]);h+='<span style="background:'+x[0]+';color:'+x[1]+'">'+f2(r.c[j])+'</span>';}
    if(r.a)h+='<span>ANCHOR</span>';
    else{var fl=Math.abs(r.z)>=2,cl=Math.abs(r.d)<0.005?'':(r.d>0?' up':' dn');h+='<span class="dl'+cl+'">'+(fl?'<b>⚑</b>':'')+f2(Math.abs(r.d)<0.005?0:r.d)+(cl===' up'?' ▲':cl===' dn'?' ▼':' ·')+'</span>';}
    h+='</div>';
  });
  gb.innerHTML=h;
  var hb=root.querySelectorAll('.gh button');
  for(i=0;i<hb.length;i++){var c=+hb[i].getAttribute('data-c'),on=c===SC;hb[i].classList.toggle('on',on);hb[i].setAttribute('aria-sort',on?(SD<0?'descending':'ascending'):'none');hb[i].textContent=(c<0?'INSTR':c===4?'Δ1M-1Y':WL[c])+(on&&c>=0?(SD<0?' ▾':' ▴'):'');}
  q('.sub').textContent='ρ to '+ANC[AI]+' · log-ret · 23-Sep-26'+(SC<0?' · grouped':' · sorted');
  detail(o);
}
function detail(o){
  o=o||order();var r=o[sel];if(!r)return;var R0=ROWS[r.i];
  if(r.a){dt.innerHTML='<b>'+R0[1]+'</b> is the anchor · pick another row';return;}
  var fl=Math.abs(r.z)>=2;
  dt.innerHTML='<b>'+R0[1]+'</b> '+R0[2]+' vs <b>'+ANC[AI]+'</b><br>1M '+f2(r.c[0])+' · 1Y '+f2(r.c[3])+' · Δ '+f2(r.d)+' · Fisher Δz '+(r.z<0?'−':'+')+Math.abs(r.z).toFixed(1)+'σ '+(fl?'<span class="fl">⚑ REGIME BREAK</span>':'· within noise');
  var rs=gb.querySelectorAll('.r');for(i=0;i<rs.length;i++)rs[i].classList.toggle('on',i===sel);
}
root.querySelector('.an').addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;AI=+b.getAttribute('data-a');var bs=root.querySelectorAll('.an button');for(i=0;i<bs.length;i++){var on=bs[i]===b;bs[i].classList.toggle('on',on);bs[i].setAttribute('aria-pressed',on?'true':'false');}compute();pick();draw();});
root.querySelector('.gh').addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;var c=+b.getAttribute('data-c');if(c<0){SC=-1;}else if(SC===c){SD=-SD;}else{SC=c;SD=-1;}draw();});
gb.addEventListener('mouseover',function(e){var r=e.target.closest('.r');if(!r)return;sel=+r.getAttribute('data-p');detail();});
gb.addEventListener('keydown',function(e){
  var k=e.key;
  if(k==='ArrowUp')sel=Math.max(0,sel-1);
  else if(k==='ArrowDown')sel=Math.min(NR-1,sel+1);
  else if(k==='s'||k==='S'){SC=SC>=4?-1:SC+1;SD=-1;draw();}
  else if(k==='g'||k==='G'){SC=-1;draw();}
  else return;
  e.preventDefault();detail();
  var on=gb.querySelector('.r.on');if(on){if(on.offsetTop<gb.scrollTop)gb.scrollTop=on.offsetTop;else if(on.offsetTop+on.offsetHeight>gb.scrollTop+gb.clientHeight)gb.scrollTop=on.offsetTop+on.offsetHeight-gb.clientHeight;}
});
function pick(){var o=order(),b=0,bz=-1;o.forEach(function(r,p){if(!r.a&&Math.abs(r.z)>bz){bz=Math.abs(r.z);b=p;}});sel=b;}
compute();pick();draw();

