.ccm-dispersion{box-sizing:border-box;width:100%;max-width:400px;background:#0B0F17;border:1px solid #1C2432;border-radius:8px;padding:8px 9px 7px;font:9px/1.3 ui-monospace,Menlo,Consolas,monospace;color:#8B98B0;font-variant-numeric:tabular-nums;outline:none}
.ccm-dispersion *{box-sizing:border-box}
.ccm-dispersion:focus-visible{box-shadow:0 0 0 1.5px #6EA8FF}
