var NM=['NVDA','MSFT','AAPL','AMZN','META','AVGO','GOOGL','TSLA','BRK.B','JPM'];
var CAP=[7.9,6.6,6.2,4.1,3.0,2.8,2.4,2.1,1.6,1.5];
var IV=[46.2,23.8,25.9,31.4,35.6,43.8,29.7,57.9,16.8,22.4];
var RV=[38.5,19.6,21.2,26.8,30.1,39.4,25.3,52.6,13.9,18.7];
var n=NM.length,ct=0,i,t;for(i=0;i<n;i++)ct+=CAP[i];
var W=CAP.map(function(c){return c/ct;});
var WP=W.map(function(w){return Math.floor(w*1000);}),rem=1000-WP.reduce(function(a,b){return a+b;},0);
W.map(function(w,k){return [w*1000-Math.floor(w*1000),k];}).sort(function(a,b){return b[0]-a[0];}).slice(0,rem).forEach(function(p){WP[p[1]]++;});
function imp(ix,v){var a=0,b=0;for(var k=0;k<n;k++){a+=W[k]*v[k];b+=W[k]*W[k]*v[k]*v[k];}return {r:(ix*ix-b)/(a*a-b),a:a};}
var BIV=23.25,BRV=17.40,N=252;
var sd=8080;
function rnd(){sd=sd+0x6D2B79F5|0;var q=Math.imul(sd^sd>>>15,1|sd);q=q+Math.imul(q^q>>>7,61|q)^q;return((q^q>>>14)>>>0)/4294967296;}
function g(){return Math.sqrt(-2*Math.log(rnd()||1e-9))*Math.cos(6.283185307*rnd());}
var HI=[],HR=[],xi=0.37,xr=0.22;
for(t=0;t<N;t++){xi+=0.07*(0.37-xi)+0.012*g()+(t>148&&t<162?0.012:0);xr+=0.06*(0.22-xr)+0.016*g()+(t>150&&t<164?0.03:0);HI.push(xi);HR.push(xr);}
function anchor(H,target){var e=target-H[N-1];return H.map(function(v,k){return Math.max(0.02,Math.min(0.98,v+e*(k/(N-1))));});}
var q=function(c){return root.querySelector(c);};
function f2(r){return (r*100).toFixed(1);}
function sg(v,d){return (v<0?'−':'+')+Math.abs(v).toFixed(d);}
function Y(v){return (1-Math.min(v,0.8)/0.8)*80;}
function draw(){
  var I=imp(BIV,IV),Rz=imp(BRV,RV),ri=I.r,rr=Rz.r,ra=Rz.a;
  var hi=anchor(HI,ri),hr=anchor(HR,rr),li='',lr='',k;
  for(k=0;k<N;k++){var x=(k/(N-1)*300).toFixed(1);li+=(k?'L':'M')+x+','+Y(hi[k]).toFixed(2);lr+=(k?'L':'M')+x+','+Y(hr[k]).toFixed(2);}
  var up='';
  for(k=0;k<N;k++){var x3=(k/(N-1)*300).toFixed(1);up+=(k?'L':'M')+x3+','+Y(Math.max(hi[k],hr[k])).toFixed(2);}
  var ur='';for(k=N-1;k>=0;k--){ur+='L'+(k/(N-1)*300).toFixed(1)+','+Y(hr[k]).toFixed(2);}
  var nr='';for(k=N-1;k>=0;k--){nr+='L'+(k/(N-1)*300).toFixed(1)+','+Y(Math.min(hi[k],hr[k])).toFixed(2);}
  var dp='';for(k=0;k<N;k++){dp+=(k?'L':'M')+(k/(N-1)*300).toFixed(1)+','+Y(hr[k]).toFixed(2);}
  q('.sp').setAttribute('d',up+ur+'Z');
  q('.sn').setAttribute('d',dp+nr+'Z');
  q('.li').setAttribute('d',li);q('.lr').setAttribute('d',lr);
  var ei=q('.ei'),er=q('.er');ei.textContent=f2(ri);er.textContent=f2(rr);ei.style.top=(Y(ri)/80*100)+'%';er.style.top=(Y(rr)/80*100)+'%';
  if(Math.abs(Y(ri)-Y(rr))<7){var m=(Y(ri)+Y(rr))/2;ei.style.top=((m-(ri>=rr?4:-4))/80*100)+'%';er.style.top=((m+(ri>=rr?4:-4))/80*100)+'%';}
  var crp=Math.round(ri*1000)/10-Math.round(rr*1000)/10,le=0;for(k=0;k<N;k++)if(hi[k]-hr[k]<=ri-rr)le++;
  q('.biv').textContent=BIV.toFixed(2);
  function sv(c,h,cl){var e=q(c);e.textContent=h;e.className=c.slice(1)+(cl?' '+cl:'');}
  sv('.s0',f2(ri));sv('.s1',f2(rr));sv('.s2',sg(crp,1)+' pts',crp>=0?'po':'ne');
  sv('.s3',I.a.toFixed(2));sv('.s4',sg(I.a-BIV,2)+' v');sv('.s5',Math.round(le/N*100)+'th');
  var s=q('.sg');
  if(crp>=10){s.className='sg rich';s.innerHTML='<b>▲ CORR RICH</b> · short basket vol / long single names';}
  else if(crp<=0){s.className='sg cheap';s.innerHTML='<b>▼ CORR CHEAP</b> · long basket vol / short single names';}
  else{s.className='sg';s.innerHTML='<b>● NEUTRAL</b> · CRP below 10 pt threshold';}
  var h='',sw=0,siv=0,srv=0;
  for(k=0;k<n;k++){var d=IV[k]-RV[k];sw+=WP[k];siv+=W[k]*IV[k];srv+=W[k]*RV[k];
    h+='<div><span><b>'+NM[k]+'</b></span><span>'+(WP[k]/10).toFixed(1)+'</span><span>'+IV[k].toFixed(1)+'</span><span>'+RV[k].toFixed(1)+'</span><span class="'+(d>=0?'po':'ne')+'">'+sg(d,1)+'</span></div>';}
  q('.rows').innerHTML=h;
  q('.tt2').innerHTML='<span>Σw</span><span>'+(sw/10).toFixed(1)+'</span><span>'+siv.toFixed(2)+'</span><span>'+srv.toFixed(2)+'</span><span>'+sg(siv-srv,2)+'</span>';
}
function bump(d){BIV=Math.max(12,Math.min(40,Math.round((BIV+d)*100)/100));var r=imp(BIV,IV).r;if(r>0.98||r<0.02){BIV=Math.round((BIV-d)*100)/100;}draw();}
q('.bm .up').addEventListener('click',function(){bump(0.25);});
q('.bm .dn').addEventListener('click',function(){bump(-0.25);});
root.addEventListener('keydown',function(e){if(e.target.tagName==='BUTTON'&&(e.key==='Enter'||e.key===' '))return;if(e.key==='+'||e.key==='='||e.key==='ArrowUp'){e.preventDefault();bump(0.25);}else if(e.key==='-'||e.key==='_'||e.key==='ArrowDown'){e.preventDefault();bump(-0.25);}});
draw();

