  R[0].push(f(F,0)+0.30*g());
  R[1].push(0.95*f(F,0)+0.04*f(F,1)+0.42*g());
  R[2].push(0.78*f(F,0)+0.13*f(F,1)+0.06*f(F,2)+0.55*g());
  R[3].push(-0.24*f(F,0)-0.08*f(F,1)-0.03*f(F,2)+0.90*g());
  R[4].push(f(U,0)+0.05*f(F,0)+0.60*g());
  R[5].push(0.8*f(C,0)+0.25*f(F,0)+0.05*f(F,1)+0.70*g());
