}
var Z=R.map(function(a){var m=0,v=0;a.forEach(function(x){m+=x;});m/=N;a.forEach(function(x){v+=(x-m)*(x-m);});var s=Math.sqrt(v/N);return a.map(function(x){return (x-m)/s;});});
