var NEG=[58,126,232],MID=[23,29,41],POS=[236,132,56],DOM=0.25,BAND=1.96/Math.sqrt(N);
function cc(r){var tt=Math.pow(Math.min(1,Math.abs(r)/DOM),0.85),c=r<0?NEG:POS,o=[0,1,2].map(function(x){return Math.round(MID[x]+(c[x]-MID[x])*tt);});var L=(0.2126*o[0]+0.7152*o[1]+0.0722*o[2])/255;return ['rgb('+o.join(',')+')',L>0.42?'#0B0F17':'#E2E8F2'];}
