  if(si===sj){q('.cp').textContent=T[si]+' autocorrelation not shown';q('.pk').textContent='';kx.innerHTML='';return;}
  var X=XC[si][sj],pk=-1,pv=0,h='';
  for(k=0;k<=2*ML;k++){if(k===ML)continue;if(Math.abs(X[k])>Math.abs(pv)){pv=X[k];pk=k;}}
  for(k=0;k<=2*ML;k++){
    var v=X[k],cv=Math.max(-0.2,Math.min(0.2,v)),y=30-cv/0.2*30,x=k*20+4,r=document.createElementNS(NS,'rect');
    r.setAttribute('x',x);r.setAttribute('width',12);r.setAttribute('y',Math.min(y,30));r.setAttribute('height',Math.max(0.6,Math.abs(30-y)));
    r.setAttribute('class',k===ML?'k0':((v<0?'ne':'po')+(Math.abs(v)<BAND?' ns':'')+(k===pk?' pkb':'')));
    bars.appendChild(r);
    var lb=k-ML;h+='<span class="'+(k===ML?'z':'')+'">'+(lb>0?'+':lb<0?'−':'')+Math.abs(lb)+'<span class="v">'+f2(v)+'</span></span>';
  }
  kx.innerHTML=h;
  q('.cp').textContent=T[si]+'ₜ vs '+T[sj]+'ₜ₊ₖ';
  var lag=pk-ML,sig=Math.abs(pv)>=BAND;
  q('.pk').innerHTML=!sig?'no lag beyond band':'peak <b>k='+(lag>0?'+':'−')+Math.abs(lag)+'</b> '+f2(pv)+' · '+(lag>0?T[si]+' leads '+T[sj]:T[sj]+' leads '+T[si])+' '+Math.abs(lag)+'m';
  q('.cp').title='lead score '+f2(LS[si][sj]);
}
gd.addEventListener('mouseover',function(e){var c=e.target.closest('.cl');if(!c)return;si=+c.getAttribute('data-i');sj=+c.getAttribute('data-j');sel();});
gd.addEventListener('keydown',function(e){
  var x=e.key;
  if(x==='ArrowLeft')sj=Math.max(0,sj-1);else if(x==='ArrowRight')sj=Math.min(K-1,sj+1);
  else if(x==='ArrowUp')si=Math.max(0,si-1);else if(x==='ArrowDown')si=Math.min(K-1,si+1);
  else if(x==='t'||x==='T'){var tmp=si;si=sj;sj=tmp;}
  else return;
  e.preventDefault();sel();
});
